        SimpleAssert.that(mixed.add(6, essenceDecl), "再混一条源质声明");
        final StubOps mixedOps = new StubOps();
        mixedOps.forcedExtract.put(itemDecl.key(), PocketReceipt.NO_CHANNEL);
